import React, { useState, useEffect } from 'react';
import {
  TextField,
  Button,
  Container,
  Box,
  Tab,
  Tabs,
  Typography,
  Paper,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  Snackbar
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import AddIcon from '@mui/icons-material/Add';

function AdminPanel() {
  const [tabValue, setTabValue] = useState(0);
  const [products, setProducts] = useState(JSON.parse(localStorage.getItem('products')) || []);
  const [newProduct, setNewProduct] = useState({ name: '', price: '', description: '', image: '' });
  const [editProductId, setEditProductId] = useState(null);
  const [deleteConfirm, setDeleteConfirm] = useState({ open: false, productId: null });
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleAddProduct = (e) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price) return;
    
    const newProductData = {
      id: Date.now(),
      ...newProduct,
      price: Number(newProduct.price)
    };
    
    setProducts([...products, newProductData]);
    setNewProduct({ name: '', price: '', description: '', image: '' });
    setSnackbar({ open: true, message: 'Product added successfully!', severity: 'success' });
  };

  const handleEditProduct = (id) => {
    const product = products.find(p => p.id === id);
    setNewProduct({ ...product });
    setEditProductId(id);
  };

  const handleSaveEdit = (e) => {
    e.preventDefault();
    setProducts(products.map(p => 
      p.id === editProductId 
        ? { ...p, ...newProduct, price: Number(newProduct.price) } 
        : p
    ));
    setNewProduct({ name: '', price: '', description: '', image: '' });
    setEditProductId(null);
    setSnackbar({ open: true, message: 'Product updated successfully!', severity: 'success' });
  };

  const handleDeleteProduct = (id) => {
    setDeleteConfirm({ open: true, productId: id });
  };

  const confirmDelete = () => {
    setProducts(products.filter(p => p.id !== deleteConfirm.productId));
    setDeleteConfirm({ open: false, productId: null });
    setSnackbar({ open: true, message: 'Product deleted successfully!', severity: 'success' });
  };

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Paper elevation={3} sx={{ p: 3, mb: 4 }}>
        <Typography variant="h4" gutterBottom color="primary" sx={{ mb: 3 }}>
          Admin Dashboard
        </Typography>
        
        <Tabs value={tabValue} onChange={handleTabChange} sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
          <Tab label="Products" />
          <Tab label="Orders" />
          <Tab label="Users" />
        </Tabs>

        {tabValue === 0 && (
          <Box>
            <Paper elevation={2} sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                {editProductId ? 'Edit Product' : 'Add New Product'}
              </Typography>
              <form onSubmit={editProductId ? handleSaveEdit : handleAddProduct}>
                <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' } }}>
                  <TextField
                    label="Product Name"
                    value={newProduct.name}
                    onChange={(e) => setNewProduct({ ...newProduct, name: e.target.value })}
                    required
                    fullWidth
                  />
                  <TextField
                    label="Price"
                    type="number"
                    value={newProduct.price}
                    onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })}
                    required
                    fullWidth
                  />
                  <TextField
                    label="Description"
                    value={newProduct.description}
                    onChange={(e) => setNewProduct({ ...newProduct, description: e.target.value })}
                    fullWidth
                    multiline
                    rows={2}
                  />
                  <TextField
                    label="Image URL"
                    value={newProduct.image}
                    onChange={(e) => setNewProduct({ ...newProduct, image: e.target.value })}
                    fullWidth
                  />
                </Box>
                <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                  <Button 
                    type="submit" 
                    variant="contained" 
                    startIcon={editProductId ? <EditIcon /> : <AddIcon />}
                  >
                    {editProductId ? 'Save Changes' : 'Add Product'}
                  </Button>
                  {editProductId && (
                    <Button 
                      onClick={() => {
                        setEditProductId(null);
                        setNewProduct({ name: '', price: '', description: '', image: '' });
                      }}
                      variant="outlined"
                    >
                      Cancel
                    </Button>
                  )}
                </Box>
              </form>
            </Paper>

            <Paper elevation={2} sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                Product List ({products.length})
              </Typography>
              {products.length === 0 ? (
                <Typography color="text.secondary">No products available.</Typography>
              ) : (
                products.map((product) => (
                  <Paper 
                    key={product.id} 
                    elevation={1} 
                    sx={{ 
                      p: 2, 
                      mb: 2, 
                      display: 'flex', 
                      justifyContent: 'space-between',
                      alignItems: 'center'
                    }}
                  >
                    <Box>
                      <Typography variant="subtitle1" fontWeight="bold">
                        {product.name}
                      </Typography>
                      <Typography color="primary">
                        ${product.price.toFixed(2)}
                      </Typography>
                      {product.description && (
                        <Typography variant="body2" color="text.secondary">
                          {product.description}
                        </Typography>
                      )}
                    </Box>
                    <Box>
                      <IconButton 
                        onClick={() => handleEditProduct(product.id)}
                        color="primary"
                        size="small"
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton 
                        onClick={() => handleDeleteProduct(product.id)}
                        color="error"
                        size="small"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </Box>
                  </Paper>
                ))
              )}
            </Paper>
          </Box>
        )}

        {tabValue === 1 && (
          <Typography variant="h6">Orders Management (Coming Soon)</Typography>
        )}

        {tabValue === 2 && (
          <Typography variant="h6">Users Management (Coming Soon)</Typography>
        )}
      </Paper>

      <Dialog open={deleteConfirm.open} onClose={() => setDeleteConfirm({ open: false, productId: null })}>
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          Are you sure you want to delete this product?
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteConfirm({ open: false, productId: null })}>Cancel</Button>
          <Button onClick={confirmDelete} color="error" variant="contained">Delete</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert 
          onClose={() => setSnackbar({ ...snackbar, open: false })} 
          severity={snackbar.severity}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
}

export default AdminPanel;
